import { Badge } from '@/components/ui/badge';
import { Breadcrumb, BreadcrumbItem, BreadcrumbLink, BreadcrumbList, BreadcrumbPage } from '@/components/ui/breadcrumb';
import { LinkButton } from '@/components/ui/button';
import { CardAction, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { EmptyContent, EmptyDescription, EmptyHeader, EmptyTitle } from '@/components/ui/empty';

/** A link with its Writer label; the last breadcrumb has no href (the current page). */
export interface PageHeaderLink { label: string; href?: string }
/** One record fact beside the title (config.record). */
export interface PageHeaderMeta { label: string; value: string }

/** The inputs of `sections.page-header`: the contract's copy fields, display-ready. */
export interface PageHeaderInput {
  header?: { eyebrow?: string };
  title: string;
  description?: string;
  breadcrumbs?: { label: string; items: readonly PageHeaderLink[] };
  actions?: readonly { label: string; href: string }[];
  meta?: readonly PageHeaderMeta[];
  /** The closed members: `config.standard`, `config.record` (meta badges beside the title) and `contact.header` (centred, no breadcrumbs). */
  config?: 'standard' | 'record' | 'contact';
}

/** `sections.page-header`: a page's breadcrumbs, title, description, record facts and actions, composed of stock aria-nova parts only. */
export default function PageHeaderSection({ header, title, description, breadcrumbs, actions = [], meta = [], config = 'standard', ...provenance }: PageHeaderInput & { [marker: `data-clossys-${string}`]: string }) {
  const links = actions.slice(0, 2).map((action, index) => <LinkButton key={action.href} href={action.href} variant={index === 0 ? 'default' : 'outline'}>{action.label}</LinkButton>);
  const eyebrow = header?.eyebrow ? <Badge variant="secondary">{header.eyebrow}</Badge> : null;
  if (config === 'contact') return <EmptyHeader data-config="contact" {...provenance}>
    {eyebrow}
    <EmptyTitle role="heading" aria-level={1}>{title}</EmptyTitle>
    {description ? <EmptyDescription>{description}</EmptyDescription> : null}
    {links.length ? <EmptyContent>{links}</EmptyContent> : null}
  </EmptyHeader>;
  const trail = breadcrumbs?.items ?? [];
  return <CardHeader data-config={config} {...provenance}>
    {trail.length > 1 ? <Breadcrumb aria-label={breadcrumbs?.label}>
      <BreadcrumbList>
        {trail.map((item, index) => <BreadcrumbItem key={`${index}:${item.label}`}>
          {item.href && index < trail.length - 1 ? <BreadcrumbLink href={item.href}>{item.label}</BreadcrumbLink> : <BreadcrumbPage>{item.label}</BreadcrumbPage>}
        </BreadcrumbItem>)}
      </BreadcrumbList>
    </Breadcrumb> : eyebrow}
    <CardTitle role="heading" aria-level={1}>
      {title}
      {config === 'record' ? meta.map(fact => <Badge key={fact.label} variant="outline">{fact.label} {fact.value}</Badge>) : null}
    </CardTitle>
    {description ? <CardDescription>{description}</CardDescription> : null}
    {links.length ? <CardAction>{links}</CardAction> : null}
  </CardHeader>;
}
